import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { BrowserRouter, Navigate, Route, Routes, useParams } from 'react-router-dom';
import { initializeTelegram } from '../core/telegram';
import { AppShell } from './AppShell';
import { SessionProvider, useSession } from './SessionProvider';
import { ToastProvider } from './ToastProvider';
import { ThemeProvider } from './ThemeProvider';
import { OverviewPage } from '../features/overview/OverviewPages';
import { SystemHealthPage } from '../features/system/SystemHealthPage';
import { SettingsPage } from '../features/settings/AiSettingsPage';
import { HandoffDetailPage, HandoffsPage, AiBacklogPage } from '../features/support/SupportPages';
import {
  DraftEditorPage,
  ExactAnswerDetailPage,
  KnowledgeDetailPage,
  KnowledgePage,
} from '../features/knowledge/KnowledgePages';
import { AdminsPage, AuditPage, MorePage, NotificationsPage } from '../features/admin/AdminPages';
import { EmptyState } from '../components/ui';
import { AnalyticsPage, AnalyticsTracePage } from '../features/analytics/AnalyticsPages';
import { LogsPage } from '../features/diagnostics/LogsPage';
import { ConfirmationProvider } from './ConfirmationProvider';

const queryClient = new QueryClient({
  defaultOptions: {
    queries: { staleTime: 15_000, retry: 1, refetchOnWindowFocus: false },
    mutations: { retry: false },
  },
});
initializeTelegram();

function CapabilityRoute({
  capability,
  children,
}: {
  capability: string;
  children: React.ReactNode;
}) {
  const { hasCapability } = useSession();
  return hasCapability(capability) ? (
    <>{children}</>
  ) : (
    <EmptyState
      icon="!"
      title="دسترسی مجاز نیست"
      description="نقش شما اجازه مشاهده این بخش را ندارد."
    />
  );
}

function LegacyConversationRedirect() {
  const { id } = useParams();
  return <Navigate to={id ? `/handoffs/${encodeURIComponent(id)}` : '/handoffs'} replace />;
}

export function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider>
        <BrowserRouter basename="/mini-app">
          <ToastProvider>
            <SessionProvider>
              <Routes>
                <Route
                  element={
                    <ConfirmationProvider>
                      <AppShell />
                    </ConfirmationProvider>
                  }
                >
                  <Route index element={<Navigate to="/overview" replace />} />
                  <Route path="overview" element={<OverviewPage />} />
                  <Route path="handoffs" element={<HandoffsPage />} />
                  <Route path="handoffs/:conversationId" element={<HandoffDetailPage />} />
                  <Route path="conversations" element={<LegacyConversationRedirect />} />
                  <Route path="conversations/:id" element={<LegacyConversationRedirect />} />
                  <Route path="ai-backlog" element={<AiBacklogPage />} />
                  <Route
                    path="analytics"
                    element={
                      <CapabilityRoute capability="analytics:read">
                        <AnalyticsPage />
                      </CapabilityRoute>
                    }
                  />
                  <Route
                    path="analytics/traces/:traceId"
                    element={
                      <CapabilityRoute capability="analytics:read">
                        <AnalyticsTracePage />
                      </CapabilityRoute>
                    }
                  />
                  <Route
                    path="knowledge"
                    element={
                      <CapabilityRoute capability="knowledge:manage">
                        <KnowledgePage />
                      </CapabilityRoute>
                    }
                  />
                  <Route
                    path="knowledge/new"
                    element={
                      <CapabilityRoute capability="knowledge:manage">
                        <DraftEditorPage />
                      </CapabilityRoute>
                    }
                  />
                  <Route
                    path="knowledge/drafts/:id"
                    element={
                      <CapabilityRoute capability="knowledge:manage">
                        <DraftEditorPage />
                      </CapabilityRoute>
                    }
                  />
                  <Route
                    path="knowledge/:id"
                    element={
                      <CapabilityRoute capability="knowledge:manage">
                        <KnowledgeDetailPage />
                      </CapabilityRoute>
                    }
                  />
                  <Route
                    path="knowledge/exact-answers/:id"
                    element={
                      <CapabilityRoute capability="knowledge:manage">
                        <ExactAnswerDetailPage />
                      </CapabilityRoute>
                    }
                  />
                  <Route
                    path="connections"
                    element={<Navigate to="/system?tab=connections" replace />}
                  />
                  <Route path="system" element={<SystemHealthPage />} />
                  <Route
                    path="diagnostics"
                    element={<Navigate to="/system?tab=diagnostics" replace />}
                  />
                  <Route
                    path="logs"
                    element={
                      <CapabilityRoute capability="diagnostics:read">
                        <LogsPage />
                      </CapabilityRoute>
                    }
                  />
                  <Route
                    path="admins"
                    element={
                      <CapabilityRoute capability="admin:manage">
                        <AdminsPage />
                      </CapabilityRoute>
                    }
                  />
                  <Route
                    path="audit"
                    element={
                      <CapabilityRoute capability="audit:read">
                        <AuditPage />
                      </CapabilityRoute>
                    }
                  />
                  <Route path="notifications" element={<NotificationsPage />} />
                  <Route
                    path="settings"
                    element={
                      <CapabilityRoute capability="settings:read">
                        <SettingsPage />
                      </CapabilityRoute>
                    }
                  />
                  <Route path="more" element={<MorePage />} />
                  <Route path="*" element={<Navigate to="/overview" replace />} />
                </Route>
              </Routes>
            </SessionProvider>
          </ToastProvider>
        </BrowserRouter>
      </ThemeProvider>
    </QueryClientProvider>
  );
}
